// Package reports computes the dashboard's reports.
package reports

import (
	"errors"
	"fmt"
	"sort"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// DayRevenue is what an organization took on one day in one currency.
type DayRevenue struct {
	Date     string         `json:"date"` // YYYY-MM-DD
	Currency money.Currency `json:"currency"`
	Amount   int64          `json:"amount"`
	Payments int            `json:"payments"`
}

// Group is how the revenue report groups days into buckets.
type Group string

// The groups of the revenue report.
const (
	GroupDay   Group = "day"
	GroupWeek  Group = "week"  // starts on Monday
	GroupMonth Group = "month" // a calendar month
)

// Bucket is what an organization took in one day, week or month. Start is the first day of the bucket (YYYY-MM-DD).
type Bucket struct {
	Start    string                   `json:"start"`
	Amounts  map[money.Currency]int64 `json:"amounts"`
	Payments int                      `json:"payments"`
}

// Report is the revenue report of an organization: its buckets in date order, in the organization's time zone.
type Report struct {
	TimeZone string   `json:"time_zone"`
	Group    Group    `json:"group"`
	Buckets  []Bucket `json:"buckets"`
}

// Errors.
var (
	ErrInvalidDate  = errors.New("invalid date")
	ErrInvalidRange = errors.New("invalid date range")
	ErrInvalidGroup = errors.New("invalid group")
)

// MaxDays is the longest range a report covers.
const MaxDays = 366

// Revenue adds up the organization's succeeded payments per day and currency, from the day from to the day to (YYYY-MM-DD,
// both included). Days are days in the organization's time zone. The result is in date order, currencies in alphabetical
// order within a day; days without payments are left out.
func Revenue(st *store.Store, orgID, from, to string) ([]DayRevenue, error) {
	start, last, err := parseRange(from, to)
	if err != nil {
		return nil, err
	}
	_, loc, err := orgLocation(st, orgID)
	if err != nil {
		return nil, err
	}
	type key struct {
		day string
		cur money.Currency
	}
	sums := map[key]*DayRevenue{}
	for _, p := range succeededPayments(st, orgID, loc, start, last) {
		k := key{p.day.Format(time.DateOnly), p.currency}
		d, ok := sums[k]
		if !ok {
			d = &DayRevenue{Date: k.day, Currency: k.cur}
			sums[k] = d
		}
		d.Amount += p.amount
		d.Payments++
	}
	out := make([]DayRevenue, 0, len(sums))
	for _, d := range sums {
		out = append(out, *d)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Date != out[j].Date {
			return out[i].Date < out[j].Date
		}
		return out[i].Currency < out[j].Currency
	})
	return out, nil
}

// RevenueReport adds up the organization's succeeded payments per day, week or month (group; the empty group is day)
// from the day from to the day to (YYYY-MM-DD, both included). Days are days in the organization's time zone. Every
// bucket from the one holding from to the one holding to is in the report, also those without payments.
func RevenueReport(st *store.Store, orgID, from, to, group string) (Report, error) {
	start, last, err := parseRange(from, to)
	if err != nil {
		return Report{}, err
	}
	g := Group(group)
	if g == "" {
		g = GroupDay
	}
	if g != GroupDay && g != GroupWeek && g != GroupMonth {
		return Report{}, fmt.Errorf("%w: %q", ErrInvalidGroup, group)
	}
	name, loc, err := orgLocation(st, orgID)
	if err != nil {
		return Report{}, err
	}
	buckets := []Bucket{}
	index := map[string]int{}
	for b := bucketStart(start, g); !b.After(bucketStart(last, g)); b = nextBucket(b, g) {
		index[b.Format(time.DateOnly)] = len(buckets)
		buckets = append(buckets, Bucket{Start: b.Format(time.DateOnly), Amounts: map[money.Currency]int64{}})
	}
	for _, p := range succeededPayments(st, orgID, loc, start, last) {
		b := &buckets[index[bucketStart(p.day, g).Format(time.DateOnly)]]
		b.Amounts[p.currency] += p.amount
		b.Payments++
	}
	return Report{TimeZone: name, Group: g, Buckets: buckets}, nil
}

// dayPayment is a succeeded payment and the day it was made on in the organization's time zone.
type dayPayment struct {
	day      time.Time // the day at UTC midnight, so calendar arithmetic does not depend on a time zone
	currency money.Currency
	amount   int64
}

// parseRange reads from and to as days (YYYY-MM-DD) at UTC midnight and checks the range.
func parseRange(from, to string) (time.Time, time.Time, error) {
	start, err := time.Parse(time.DateOnly, from)
	if err != nil {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: from %q", ErrInvalidDate, from)
	}
	last, err := time.Parse(time.DateOnly, to)
	if err != nil {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: to %q", ErrInvalidDate, to)
	}
	if last.Before(start) {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: to is before from", ErrInvalidRange)
	}
	if last.Sub(start) >= MaxDays*24*time.Hour {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: at most %d days", ErrInvalidRange, MaxDays)
	}
	return start, last, nil
}

// orgLocation returns the organization's time zone name and its location.
func orgLocation(st *store.Store, orgID string) (string, *time.Location, error) {
	org, ok := st.Org(orgID)
	if !ok {
		return "", nil, store.ErrNotFound
	}
	loc, err := time.LoadLocation(org.TimeZone)
	if err != nil {
		return "", nil, fmt.Errorf("organization time zone %q: %w", org.TimeZone, err)
	}
	return org.TimeZone, loc, nil
}

// succeededPayments returns the organization's succeeded payments made on the days start to last (both included), in
// loc. A payment's day is the day it was made on in loc, so a day has the length it really has there.
func succeededPayments(st *store.Store, orgID string, loc *time.Location, start, last time.Time) []dayPayment {
	var out []dayPayment
	for _, p := range st.Payments(orgID, "") {
		if p.Status != store.PaymentSucceeded {
			continue
		}
		y, m, d := p.CreatedAt.In(loc).Date()
		day := time.Date(y, m, d, 0, 0, 0, 0, time.UTC)
		if day.Before(start) || day.After(last) {
			continue
		}
		out = append(out, dayPayment{day: day, currency: p.Currency, amount: p.Amount})
	}
	return out
}

// bucketStart returns the first day of the bucket that holds the day d.
func bucketStart(d time.Time, g Group) time.Time {
	switch g {
	case GroupWeek:
		return d.AddDate(0, 0, -((int(d.Weekday()) + 6) % 7))
	case GroupMonth:
		return time.Date(d.Year(), d.Month(), 1, 0, 0, 0, 0, time.UTC)
	}
	return d
}

// nextBucket returns the first day of the bucket after the one starting on d.
func nextBucket(d time.Time, g Group) time.Time {
	switch g {
	case GroupWeek:
		return d.AddDate(0, 0, 7)
	case GroupMonth:
		return d.AddDate(0, 1, 0)
	}
	return d.AddDate(0, 0, 1)
}

