func TestRevenueUsesOrganizationTimeZone(t *testing.T) {
	f := newRevenueFixture(t, "America/New_York")
	ny, err := time.LoadLocation("America/New_York")
	if err != nil {
		t.Fatal(err)
	}
	// DST starts in New York on 2026-03-08 at 02:00.
	at := func(d, h, m int) time.Time { return time.Date(2026, 3, d, h, m, 0, 0, ny) }
	f.pay(t, 999, money.USD, store.PaymentSucceeded, at(1, 23, 30)) // 2026-03-02 04:30 UTC, before the range
	f.pay(t, 1000, money.USD, store.PaymentSucceeded, at(2, 21, 0)) // 2026-03-03 02:00 UTC, still 2026-03-02 here
	f.pay(t, 200, money.USD, store.PaymentSucceeded, at(7, 23, 30)) // last moment of an EST day
	f.pay(t, 300, money.USD, store.PaymentSucceeded, at(8, 0, 30))  // first moment of the 23-hour day
	f.pay(t, 400, money.USD, store.PaymentSucceeded, at(8, 23, 30)) // end of the 23-hour day
	f.pay(t, 500, money.USD, store.PaymentSucceeded, at(9, 0, 30))  // first moment after it
	got, err := Revenue(f.st, f.org.ID, "2026-03-02", "2026-03-09")
	if err != nil {
		t.Fatal(err)
	}
	want := []DayRevenue{
		{Date: "2026-03-02", Currency: money.USD, Amount: 1000, Payments: 1},
		{Date: "2026-03-07", Currency: money.USD, Amount: 200, Payments: 1},
		{Date: "2026-03-08", Currency: money.USD, Amount: 700, Payments: 2},
		{Date: "2026-03-09", Currency: money.USD, Amount: 500, Payments: 1},
	}
	if len(got) != len(want) {
		t.Fatalf("Revenue = %+v", got)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("day %d = %+v, want %+v", i, got[i], want[i])
		}
	}
}

func TestRevenueReportGroups(t *testing.T) {
	day := func(d, h int) time.Time { return time.Date(2026, 3, d, h, 0, 0, 0, time.UTC) }
	f := newRevenueFixture(t, "UTC")
	f.pay(t, 100, money.USD, store.PaymentSucceeded, time.Date(2026, 2, 10, 10, 0, 0, 0, time.UTC))
	f.pay(t, 200, money.USD, store.PaymentSucceeded, time.Date(2026, 2, 20, 10, 0, 0, 0, time.UTC))
	f.pay(t, 1000, money.USD, store.PaymentSucceeded, day(2, 10))
	f.pay(t, 300, money.USD, store.PaymentSucceeded, day(4, 10))
	f.pay(t, 70, money.EUR, store.PaymentSucceeded, day(8, 10))
	f.pay(t, 999, money.USD, store.PaymentFailed, day(8, 11))
	f.pay(t, 500, money.USD, store.PaymentSucceeded, day(9, 10))
	f.pay(t, 50, money.USD, store.PaymentSucceeded, time.Date(2026, 4, 2, 23, 0, 0, 0, time.UTC))
	f.pay(t, 9, money.USD, store.PaymentSucceeded, time.Date(2026, 4, 3, 10, 0, 0, 0, time.UTC))

	for _, c := range []struct {
		name, from, to, group string
		want                  []Bucket
	}{
		{"weeks", "2026-03-04", "2026-04-02", "week", []Bucket{
			{Start: "2026-03-02", Amounts: map[money.Currency]int64{money.USD: 300, money.EUR: 70}, Payments: 2},
			{Start: "2026-03-09", Amounts: map[money.Currency]int64{money.USD: 500}, Payments: 1},
			{Start: "2026-03-16", Amounts: map[money.Currency]int64{}},
			{Start: "2026-03-23", Amounts: map[money.Currency]int64{}},
			{Start: "2026-03-30", Amounts: map[money.Currency]int64{money.USD: 50}, Payments: 1},
		}},
		{"months", "2026-02-15", "2026-04-02", "month", []Bucket{
			{Start: "2026-02-01", Amounts: map[money.Currency]int64{money.USD: 200}, Payments: 1},
			{Start: "2026-03-01", Amounts: map[money.Currency]int64{money.USD: 1300, money.EUR: 70}, Payments: 3},
			{Start: "2026-04-01", Amounts: map[money.Currency]int64{money.USD: 50}, Payments: 1},
		}},
		{"days by default", "2026-03-04", "2026-03-05", "", []Bucket{
			{Start: "2026-03-04", Amounts: map[money.Currency]int64{money.USD: 300}, Payments: 1},
			{Start: "2026-03-05", Amounts: map[money.Currency]int64{}},
		}},
	} {
		got, err := RevenueReport(f.st, f.org.ID, c.from, c.to, c.group)
		if err != nil {
			t.Fatalf("%s: %v", c.name, err)
		}
		if !reflect.DeepEqual(got.Buckets, c.want) {
			t.Errorf("%s: buckets = %+v, want %+v", c.name, got.Buckets, c.want)
		}
	}
}

