			{Start: "2026-03-01", Amounts: map[money.Currency]int64{money.USD: 1300, money.EUR: 70}, Payments: 3},
			{Start: "2026-04-01", Amounts: map[money.Currency]int64{money.USD: 50}, Payments: 1},
		}},
