			t.Errorf("%s: buckets = %+v, want %+v", c.name, got.Buckets, c.want)
		}
	}
}

func TestRevenueReportWeekStartsOnMonday(t *testing.T) {
	f := newRevenueFixture(t, "UTC")
	f.pay(t, 100, money.USD, store.PaymentSucceeded, time.Date(2026, 3, 8, 23, 59, 0, 0, time.UTC))
	got, err := RevenueReport(f.st, f.org.ID, "2026-03-08", "2026-03-08", "week")
	if err != nil {
		t.Fatal(err)
	}
	if len(got.Buckets) != 1 || got.Buckets[0].Start != "2026-03-02" || got.Buckets[0].Payments != 1 {
		t.Fatalf("Sunday's payment = %+v", got.Buckets)
	}
}

func TestRevenueReportMetadata(t *testing.T) {
	f := newRevenueFixture(t, "Europe/Berlin")
	got, err := RevenueReport(f.st, f.org.ID, "2026-03-01", "2026-03-01", "")
	if err != nil {
		t.Fatal(err)
	}
	if got.TimeZone != "Europe/Berlin" || got.Group != GroupDay {
		t.Fatalf("report = %+v", got)
	}
}

func TestRevenueReportErrors(t *testing.T) {
	f := newRevenueFixture(t, "UTC")
	for _, c := range []struct {
		from, to, group string
		want            error
	}{
		{"", "2026-03-05", "day", ErrInvalidDate},
		{"2026-03-01", "2026/03/05", "day", ErrInvalidDate},
		{"2026-03-05", "2026-03-01", "day", ErrInvalidRange},
		{"2026-01-01", "2027-01-02", "month", ErrInvalidRange},
		{"2026-03-01", "2026-03-05", "quarter", ErrInvalidGroup},
	} {
		if _, err := RevenueReport(f.st, f.org.ID, c.from, c.to, c.group); !errors.Is(err, c.want) {
			t.Errorf("RevenueReport(%s, %s, %s) = %v, want %v", c.from, c.to, c.group, err, c.want)
		}
	}
}

